<script>
document.body.classList.add('course-workspace-page');const showTab=t=>{t=document.querySelector(`[data-course-tab="${t}"]`)?t:'overview';document.querySelectorAll('[data-course-tab]').forEach(e=>e.classList.toggle('is-active',e.dataset.courseTab===t));document.querySelectorAll('[data-course-panel]').forEach(e=>e.hidden=e.dataset.coursePanel!==t);document.querySelectorAll('[data-tab-action]').forEach(e=>e.classList.toggle('hidden',e.dataset.tabAction!==t))};addEventListener('hashchange',()=>showTab(location.hash.slice(1)));showTab(location.hash.slice(1)||'overview');const addChapterModal=document.getElementById('addChapterModal'),setAddChapterModal=open=>{addChapterModal.classList.toggle('hidden',!open);addChapterModal.classList.toggle('flex',open);document.body.classList.toggle('overflow-hidden',open);if(open)setTimeout(()=>document.getElementById('addChapterTitleInput').focus(),0)};document.querySelectorAll('[data-open-section]').forEach(b=>b.onclick=()=>setAddChapterModal(true));document.querySelectorAll('[data-close-add-chapter]').forEach(b=>b.onclick=()=>setAddChapterModal(false));addChapterModal.addEventListener('click',e=>{if(e.target===addChapterModal)setAddChapterModal(false)});addEventListener('keydown',e=>{if(e.key==='Escape'&&!addChapterModal.classList.contains('hidden'))setAddChapterModal(false)});const scormToggle=document.getElementById('scormToggle'),scormFields=document.getElementById('scormUploadFields'),scormInput=document.getElementById('scormPackageInput'),scormSummary=document.getElementById('scormFileSummary'),syncScorm=()=>{const enabled=scormToggle.checked;scormFields.classList.toggle('hidden',!enabled);scormInput.required=enabled};scormToggle.addEventListener('change',syncScorm);scormInput.addEventListener('change',()=>{const file=scormInput.files[0];scormSummary.classList.toggle('hidden',!file);scormSummary.classList.toggle('flex',!!file);if(file){scormFileName.textContent=file.name;scormFileSize.textContent=file.size<1048576?`${Math.ceil(file.size/1024)} KB`:`${(file.size/1048576).toFixed(1)} MB`}});removeScormFile.addEventListener('click',()=>{scormInput.value='';scormSummary.classList.add('hidden');scormSummary.classList.remove('flex')});syncScorm();@if($errors->addChapter->any())setAddChapterModal(true);@endif document.querySelectorAll('.lesson-select').forEach(b=>b.onclick=()=>{lessonWorkspace.innerHTML=`<div class="w-full max-w-xl p-8 text-left"><p class="text-xs text-gray-500">${b.dataset.type}</p><h2 class="mt-2 text-xl font-semibold"></h2><p class="mt-3 text-sm text-gray-500">Open the lesson editor to change content, resources, preview access, and quiz settings.</p><a class="mt-5 inline-flex rounded bg-gray-900 px-4 py-2 text-xs text-white" href="${b.dataset.edit}">Edit lesson</a></div>`;lessonWorkspace.querySelector('h2').textContent=b.dataset.title});const modal=document.getElementById('sectionModal');document.querySelectorAll('[data-edit-section]').forEach(b=>b.onclick=()=>{editSectionTitle.value=b.dataset.title;editSectionForm.action=`/admin/courses/{{$course->id}}/sections/${b.dataset.editSection}`;modal.classList.remove('hidden');modal.classList.add('flex')});document.querySelector('[data-close-modal]')?.addEventListener('click',()=>{modal.classList.add('hidden');modal.classList.remove('flex')});const editor=document.getElementById('descriptionEditor');document.querySelectorAll('[data-editor-command]').forEach(b=>b.onmousedown=e=>{e.preventDefault();let[c,v]=b.dataset.editorCommand.split(':');if(c==='createLink'){const u=prompt('Link URL');if(u&&/^https?:\/\//i.test(u))document.execCommand(c,false,u)}else if(c==='insertTable')document.execCommand('insertHTML',false,'<table><tr><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td></tr></table><p><br></p>');else document.execCommand(c,false,v||null);editor.focus()});document.querySelector('[data-editor-block]').onchange=e=>document.execCommand('formatBlock',false,e.target.value);document.querySelector('[data-editor-color]').oninput=e=>document.execCommand('foreColor',false,e.target.value);courseSettingsForm.onsubmit=()=>descriptionInput.value=editor.innerHTML.trim();const syncPaid=()=>{freeInput.value=paidToggle.checked?'0':'1';priceFields.classList.toggle('hidden',!paidToggle.checked)};paidToggle.onchange=syncPaid;syncPaid();const _uploadUrl='{{route('admin.media.upload')}}',_csrf='{{csrf_token()}}';@include('admin.courses.material-script',['materialOwner'=>$course])
